from common import *
P=R/'projects/game-math-triangle-addresses-v2';H=P/'production/concept-fit-v2';T=read(H/'timeline.json');D=P/'publishing/revisions/concept-fit-v2';D.mkdir(parents=True,exist_ok=True)
en=['From a plane to a position inside a triangle', 'Relating side lengths and angles', 'Three reference points on a roof', 'Why triangle area helps locate a point', 'A finite panel and its infinite plane', 'Three ways to compute area', 'From two-point interpolation to three vertex weights', 'Representing position with three weights', 'Translate the triangle and its point together', 'Compute points inside and outside', 'Read weights back from a point', 'Weights from signed-area ratios', 'Same screen location at different depths', 'A projection and the original point are different', 'Projection does not test coplanarity', 'Check plane distance and triangle membership separately', 'An increasingly thin reference triangle', 'Find attributes at the verified position', 'Interpolate color using the same weights', 'Change attributes separately from position', 'Roof and wall positions and colors', 'Check distance, plane and weights together']
assert len(en)==len(T['scenes'])==22
def stamp(t):n=int(t);return f'{n//60:02}:{n%60:02}'
for lang in ['ko','en']:
 old=(P/f'publishing/upload-description.{lang}.txt').read_text(encoding='utf8');footer='🎮'+old.split('🎮',1)[1]
 intro='같은 평면 위에 있다고 삼각형 안에 있는 것은 아닙니다. 건물의 기준점과 표면 색을 관찰한 뒤, 삼각형의 길이·넓이·무게중심 좌표·안팎 판정·깊이와 색 보간을 기존 강의 순서대로 연결합니다.' if lang=='ko' else 'A point on a plane need not lie inside its triangle. Observe building reference points and surface colors, then connect triangle lengths, area, barycentric coordinates, membership, depth and attribute interpolation in the original lesson order.'
 note='게임 화면의 윤곽은 설명용 표식입니다. 실제 게임의 내부 좌표·메시·물리 구현을 측정한 결과로 제시하지 않습니다. 별도 배경음악은 추가하지 않았습니다.' if lang=='ko' else 'Game contours are editorial guides, not measurements of internal coordinates, meshes or physics. No separate background-music track was added.'
 chapters='\n'.join(stamp(0 if i==0 else s['start'])+' '+(s['title'] if lang=='ko' else en[i]) for i,s in enumerate(T['scenes']))
 credits='\n\n'+('게임 화면 출처' if lang=='ko' else 'Gameplay sources')+'\nTownscaper — Oskar Stalberg / Raw Fury. Official press-kit announcement trailer: construction and differently colored surfaces.\nhttps://rawfury.com/games/townscaper/\n'
 (D/f'upload-description.{lang}.txt').write_text(intro+'\n\n'+note+'\n\n'+('챕터' if lang=='ko' else 'Chapters')+'\n'+chapters+'\n'+stamp(T['seconds']-10)+' '+('멤버십 감사와 코칭 안내' if lang=='ko' else 'Membership thanks and programming coaching')+'\n\n'+footer.rstrip()+credits,encoding='utf8')
save(H/'description-drafts.json',dict(status='local drafts only',files=[dict(path=rel(x),sha256=sha(x)) for x in D.glob('*.txt')],creditsAtBottom=True,uploadAuthorized=False))
